    '  loomy log [-n N]        the last N events (20 by default), in local time') _T='  loomy log [-n N]        les N derniers événements (20 par défaut), à l'\''heure locale' ;;
    '  loomy log -f            then follows the log continuously') _T='  loomy log -f            puis suit le journal en continu' ;;
    '  loomy log --raw         raw JSON lines (.loomy/logs/events.jsonl)') _T='  loomy log --raw         lignes JSON brutes (.loomy/logs/events.jsonl)' ;;
    '  loomy log --since YYYY-MM-DD   from that date (monthly archives included)') _T='  loomy log --since AAAA-MM-JJ   à partir de cette date (archives mensuelles comprises)' ;;
    '  loomy log --csv         costs as CSV (delegations and Claude Code work, without the task text)') _T='  loomy log --csv         coûts en CSV (délégations et travail de Claude Code, sans le texte des tâches)' ;;
    '  loomy log --root <dir>  works on another project folder') _T='  loomy log --root <dir>  agit sur un autre dossier de projet' ;;
    'Starts or resumes the lead agent session of a Loomy project. Bash 3.2 compatible.') _T='Démarre ou reprend la session de l'\''orchestrateur d'\''un projet Loomy. Compatible bash 3.2.' ;;
    '  loomy start              menu: resume the last session, new session, or show the commands') _T='  loomy start              menu : reprendre la dernière session, nouvelle session, ou afficher les commandes' ;;
    '  loomy start --resume     resumes the last session of this folder directly (on this machine)') _T='  loomy start --resume     reprend directement la dernière session de ce dossier (sur cette machine)' ;;
    '  loomy start --new        opens a new session with the prompt suited to the project phase') _T='  loomy start --new        ouvre une nouvelle session avec le prompt adapté à la phase du projet' ;;
    '  loomy start --print      only shows the commands') _T='  loomy start --print      affiche seulement les commandes' ;;
    '  loomy start --watch      also opens live tracking next to the session (tmux, iTerm2 or a new window)') _T='  loomy start --watch      ouvre aussi le suivi en direct à côté de la session (tmux, iTerm2 ou nouvelle fenêtre)' ;;
    '                           (default when loomy config start_watch yes; --no-watch to skip it)') _T='                           (par défaut si loomy config start_watch yes ; --no-watch pour l'\''éviter)' ;;
    '  loomy start --root <dir> works on another project folder') _T='  loomy start --root <dir> agit sur un autre dossier de projet' ;;
    'Project and bootstrap status for Loomy. Bash 3.2 compatible.') _T='Statut du projet et du bootstrap pour Loomy. Compatible bash 3.2.' ;;
    '  ai-status.sh                 prints the status') _T='  ai-status.sh                 affiche le statut' ;;
    '  ai-status.sh set <phase>     records the current bootstrap phase (used by the agents)') _T='  ai-status.sh set <phase>     enregistre la phase en cours du bootstrap (utilisé par les agents)' ;;
    '  ai-status.sh --watch [N]     refreshes every N seconds (1 by default); q c l s (see the footer)') _T='  ai-status.sh --watch [N]     rafraîchit l'\''affichage toutes les N secondes (1 par défaut) ; q c l s (voir le pied d'\''écran)' ;;
    '  --compact / --full           tight view (for a narrow pane) or full view; watch picks one from the terminal size') _T='  --compact / --full           vue resserrée (pour un panneau étroit) ou complète ; watch choisit selon la taille du terminal' ;;
    '  ai-status.sh --root <dir>    works on another project folder') _T='  ai-status.sh --root <dir>    agit sur un autre dossier de projet' ;;
    '  --fix       Offers and applies the possible fixes (with confirmation)') _T='  --fix       Propose et applique les corrections possibles (avec confirmation)' ;;
    '  --live      Tests each model of the matrix with a real minimal call (a few cents)') _T='  --live      Teste chaque modèle de la matrice par un appel minimal réel (quelques centimes)' ;;
    '  --compact   Short output (used by the questionnaire)') _T='  --compact   Affichage court (utilisé par le questionnaire)' ;;
    '  --root DIR  Project to check (default: current project)') _T='  --root DIR  Projet à analyser (défaut : projet courant)' ;;
    'Exit code: 0 when the minimum is met, 1 otherwise.') _T='Code de sortie : 0 si le minimum est atteint, 1 sinon.' ;;
    'Commands:') _T='Commandes :' ;;
    '  (none)                Shows the role → model / effort / tool matrix for this project') _T='  (aucune)              Affiche la matrice rôle → modèle / effort / outil pour ce projet' ;;
    '  get <role>            One "family model effort" line (for scripts)') _T='  get <rôle>            Une ligne "famille modèle effort" (pour les scripts)' ;;
    '  markdown              Matrix as Markdown (for .ai/AI_MODEL_ROUTING.md)') _T='  markdown              Matrice au format Markdown (pour .ai/AI_MODEL_ROUTING.md)' ;;
    '  all                   Matrix of the 4 environments side by side (Markdown)') _T='  all                   Matrice des 4 environnements côte à côte (Markdown)' ;;
    '  claude-agents [DIR]   Generates the Claude Code subagents (default: <project>/.claude/agents)') _T='  claude-agents [DIR]   Génère les sous-agents Claude Code (défaut : <projet>/.claude/agents)' ;;
    '  codex-profiles        TOML excerpt of the Codex profiles per role (to add to ~/.codex/config.toml)') _T='  codex-profiles        Extrait TOML des profils Codex par rôle (à ajouter à ~/.codex/config.toml)' ;;
    '  lead                  Launch command of the main session (lead agent)') _T='  lead                  Commande de lancement de la session principale (orchestrateur)' ;;
    'Options:') _T='Options :' ;;
    '  --root DIR            Project (default: current project)') _T='  --root DIR            Projet (défaut : projet courant)' ;;
    '  --env ENV             claude | codex | hybrid-claude | hybrid-codex (default: detected)') _T='  --env ENV             claude | codex | hybrid-claude | hybrid-codex (défaut : détecté)' ;;
    '  --profile P           econome | equilibre | qualite (default: brief, otherwise equilibre)') _T='  --profile P           econome | equilibre | qualite (défaut : brief, sinon equilibre)' ;;
    'Roles: lead architect debugger security reviewer developer executor explorer documenter') _T='Rôles : lead architect debugger security reviewer developer executor explorer documenter' ;;
    '  --yes             No questions: default values (or those from --answers)') _T='  --yes             Pas de questions : valeurs par défaut (ou celles de --answers)' ;;
    '  --answers FILE    Reuse the answers of an existing brief (front matter key: value)') _T='  --answers FILE    Reprendre les réponses d'\''un brief existant (front matter key: value)' ;;
    '  --no-clipboard    Don'\''t copy the startup prompt to the clipboard') _T='  --no-clipboard    Ne pas copier le prompt de démarrage dans le presse-papiers' ;;
    '  -h, --help        Show this help') _T='  -h, --help        Afficher cette aide' ;;
    'Keys: ↑↓ choose, ⏎ confirm, ← back to the previous question.') _T='Touches : ↑↓ choisir, ⏎ valider, ← revenir à la question précédente.' ;;
    'Variable: NO_COLOR=1 turns colours off.') _T='Variable : NO_COLOR=1 désactive les couleurs.' ;;
    'Usage: loomy init [folder] [options]') _T='Usage : loomy init [dossier] [options]' ;;
    'Without a folder: offers the current folder, or to create a new one from the project name.') _T='Sans dossier : propose le dossier courant, ou d'\''en créer un nouveau à partir du nom du projet.' ;;
    'With a folder: creates it if it doesn'\''t exist.') _T='Avec un dossier : le crée s'\''il n'\''existe pas.' ;;
    'New project: copies START.md and .loomy/ into the folder, then runs the questionnaire.') _T='Nouveau projet : copie START.md et .loomy/ dans le dossier, puis lance le questionnaire.' ;;
    'Project already set up: offers to resume, update, redo the questionnaire or reset.') _T='Projet déjà initialisé : propose de reprendre, mettre à jour, refaire le questionnaire ou réinitialiser.' ;;
    '  --update          Updates the project'\''s Loomy files (scripts, templates); keeps brief, phase and log') _T='  --update          Met à jour les fichiers Loomy du projet (scripts, modèles) ; garde brief, phase et journal' ;;
    '  --reset           Resets the bootstrap: START.md copied again, phase reset, questionnaire run again') _T='  --reset           Réinitialise le bootstrap : START.md recopié, phase remise à zéro, questionnaire relancé' ;;
    '  --no-wizard       Install only, without the questionnaire') _T='  --no-wizard       Installer seulement, sans le questionnaire' ;;
    '  --yes             Fill in the brief without questions, with default values') _T='  --yes             Remplir le brief sans questions, avec les valeurs par défaut' ;;
    '  --answers FILE    Reuse the answers of an existing brief.md') _T='  --answers FICHIER Reprendre les réponses d'\''un brief.md existant' ;;
    'Usage: loomy worktrees <task> [base-branch]') _T='Usage : loomy worktrees <tâche> [branche-de-base]' ;;
    'Creates two separate worktrees (codex/<task> and claude/<task>) next to the repository, for parallel mode.') _T='Crée deux worktrees séparés (codex/<tâche> et claude/<tâche>) à côté du dépôt, pour le mode parallèle.' ;;
    'Example: loomy worktrees auth-refactor main') _T='Exemple : loomy worktrees auth-refactor main' ;;
    '[Loomy] Resume context for project "%s"%s.') _T='[Loomy] Contexte de reprise du projet « %s »%s.' ;;
    '- Bootstrap finished: START.md no longer has authority. Follow AGENTS.md and CLAUDE.md; you remain the lead agent.') _T='- Bootstrap terminé : START.md n'\''a plus d'\''autorité. Suis AGENTS.md et CLAUDE.md ; tu restes l'\''orchestrateur.' ;;
    '- Bootstrap in progress, phase %s of 10: %s%s. %s') _T='- Bootstrap en cours, phase %s sur 10 : %s%s. %s' ;;
    '- Resume START.md from this phase. Record every phase change, before any other action: .loomy/scripts/ai-status.sh set <phase>.') _T='- Reprends START.md à partir de cette phase. Enregistre chaque changement de phase, avant toute autre action : .loomy/scripts/ai-status.sh set <phase>.' ;;
    '- What the user needs to do now: %s') _T='- Ce que l'\''utilisateur doit faire maintenant : %s' ;;
    '- Brief (.loomy/brief.md): mode %s, lead %s, profile %s, risk %s. Role routing: .loomy/scripts/ai-route.sh; delegations: .loomy/scripts/delegate-to-claude.sh and delegate-to-codex.sh.') _T='- Brief (.loomy/brief.md) : mode %s, lead %s, profil %s, risque %s. Routage des rôles : .loomy/scripts/ai-route.sh ; délégations : .loomy/scripts/delegate-to-claude.sh et delegate-to-codex.sh.' ;;
    '- Latest delegations: %s.') _T='- Dernières délégations : %s.' ;;
    '- Git: branch %s, %s modified file(s) not committed.') _T='- Git : branche %s, %s fichier(s) modifié(s) non commité(s).' ;;
    '- Local AI files: never version AGENTS.md, CLAUDE.md, .ai/, .claude/, .codex/, .loomy/ or START.md (never git add -f).') _T='- Fichiers IA locaux : ne versionne jamais AGENTS.md, CLAUDE.md, .ai/, .claude/, .codex/, .loomy/ ni START.md (jamais de git add -f).' ;;
    '- AI files in a separate private repository: don'\''t version them in the project repository; back them up at the end of each step with .loomy/scripts/ai-privacy.sh sync.') _T='- Fichiers IA dans un dépôt privé séparé : ne les versionne pas dans le dépôt du projet ; sauvegarde-les en fin d'\''étape avec .loomy/scripts/ai-privacy.sh sync.' ;;
    '- Delegations: always run the bridges in the foreground and wait for them to finish (in the background they stop if the session closes). Announce each one in one line before (role, model, task, rough duration) and after (result, duration).') _T='- Délégations : lance toujours les bridges au premier plan et attends leur fin (en arrière-plan, elles s'\''arrêtent si la session se ferme). Annonce chacune en une ligne avant (rôle, modèle, tâche, durée indicative) et après (résultat, durée).' ;;
    '- Phase change: announce it on one line "Phase n/10 · Name", then what you are doing and what you expect from the user.') _T='- Changement de phase : annonce-le sur une ligne « Phase n/10 · Nom », puis ce que tu fais et ce que tu attends de l'\''utilisateur.' ;;
    '- To start: tell the user, in one or two sentences, where the project stands and what you propose to do now.') _T='- Pour commencer : dis à l'\''utilisateur, en une ou deux phrases, où en est le projet et ce que tu proposes de faire maintenant.' ;;
    'no answer (connection, plan or model name)') _T='pas de réponse (connexion, forfait ou nom de modèle)' ;;
    'used by this project') _T='utilisé par ce projet' ;;
    '| Role | Scope | Tool | Model | Effort | How to call it |') _T='| Rôle | Périmètre | Outil | Modèle | Effort | Comment l'\''appeler |' ;;
    '| Role | Full Claude Code | Full Codex | Hybrid, Claude lead | Hybrid, Codex lead |') _T='| Rôle | Full Claude Code | Full Codex | Hybride, lead Claude | Hybride, lead Codex |' ;;
    'Agent templates not found: %s') _T='Modèles d'\''agents introuvables : %s' ;;
    'Codex lead: no native Claude subagent. Claude roles go through delegate-to-claude.sh.') _T='Lead Codex : pas de sous-agent Claude natif. Les rôles Claude passent par delegate-to-claude.sh.' ;;
    'Loomy — Codex profiles per role (profile %s, catalog from %s)') _T='Loomy — profils Codex par rôle (profil %s, catalogue du %s)' ;;
    'Error: the task name starts with a letter or digit, then letters, digits, dots, underscores and hyphens.') _T='Erreur : le nom de tâche commence par une lettre ou un chiffre, puis lettres, chiffres, points, tirets bas et tirets.' ;;
    'Error: run this script inside a Git repository.') _T='Erreur : lancez ce script dans un dépôt Git.' ;;
    'Error: the working tree must be clean before creating parallel worktrees.') _T='Erreur : le répertoire de travail doit être propre avant de créer des worktrees parallèles.' ;;
    'Commit or stash the current changes first.') _T='Committez ou mettez de côté (stash) les changements en cours d'\''abord.' ;;
    'Error: the branch already exists: %s') _T='Erreur : la branche existe déjà : %s' ;;
    'Error: the path already exists: %s') _T='Erreur : le chemin existe déjà : %s' ;;
    'Parallel worktrees') _T='Worktrees parallèles' ;;
    'task %s · from %s') _T='tâche %s · à partir de %s' ;;
    'Branch') _T='Branche' ;;
    'NEXT STEPS') _T='ÉTAPES SUIVANTES' ;;
    'Open the Codex path in Codex, and the Claude path in Claude Code.') _T='Ouvre le chemin Codex dans Codex, et le chemin Claude dans Claude Code.' ;;
    'Give each tool a distinct scope and the same acceptance criteria.') _T='Donne à chaque outil un périmètre distinct et les mêmes critères d'\''acceptation.' ;;
    'Each tool checks and commits before integration.') _T='Chaque outil vérifie et committe avant l'\''intégration.' ;;
    'removal after integration: git worktree remove <path>') _T='suppression après intégration : git worktree remove <chemin>' ;;
    'Usage: %s <architect|debugger|security|reviewer|explorer> "task"') _T='Usage : %s <architect|debugger|security|reviewer|explorer> "tâche"' ;;
    'Old names accepted: architecture, debug, review, research.') _T='Anciens noms acceptés : architecture, debug, review, research.' ;;
    'Possible overrides: DELEGATE_CLAUDE_MODEL, DELEGATE_CLAUDE_EFFORT, DELEGATE_CLAUDE_MAX_TURNS, AI_ROUTE_PROFILE') _T='Surcharges possibles : DELEGATE_CLAUDE_MODEL, DELEGATE_CLAUDE_EFFORT, DELEGATE_CLAUDE_MAX_TURNS, AI_ROUTE_PROFILE' ;;
    'Error: the Claude Code CLI ('\''claude'\'') is not in the PATH. Run loomy doctor.') _T='Erreur : la CLI Claude Code ('\''claude'\'') est introuvable dans le PATH. Lancez loomy doctor.' ;;
    'Act as a senior, independent code reviewer. Inspect the repository or the diff the task is about. Only report concrete defects: regressions, missing tests, dangerous assumptions or needless complexity. Don'\''t modify any file. Give concise findings, ranked by severity, with file references and evidence.') _T='Agis comme relecteur de code senior et indépendant. Inspecte le dépôt ou le diff concerné par la tâche. Ne signale que des défauts concrets : régressions, tests manquants, hypothèses dangereuses ou complexité inutile. Ne modifie aucun fichier. Rends des constats concis, classés par gravité, avec références de fichiers et preuves.' ;;
    'Act as an independent software architect. Critique the proposed or current architecture against the task and the repository'\''s constraints: key trade-offs, coupling, maintainability, scaling and simpler alternatives. Don'\''t modify any file. Give concise, justified recommendations.') _T='Agis comme architecte logiciel indépendant. Critique l'\''architecture proposée ou actuelle au regard de la tâche et des contraintes du dépôt : arbitrages importants, couplage, maintenabilité, montée en charge et alternatives plus simples. Ne modifie aucun fichier. Rends des recommandations concises et justifiées.' ;;
    'Act as an independent debugging specialist. Examine the evidence available in the repository and the logs. Identify the likely causes, rank the hypotheses and propose the smallest, most discriminating checks or fixes. Don'\''t modify any file. Avoid lists of speculative fixes.') _T='Agis comme spécialiste indépendant du débogage. Examine les preuves disponibles dans le dépôt et les logs. Identifie les causes probables, classe les hypothèses et propose les vérifications ou correctifs les plus petits et les plus discriminants. Ne modifie aucun fichier. Évite les listes de correctifs spéculatifs.' ;;
    'Act as an independent security reviewer. Only inspect the scope the task is about. Identify concrete security weaknesses with their exploitation context, evidence, affected files and recommended fix. Don'\''t modify any file. Separate confirmed issues from hypotheses.') _T='Agis comme relecteur sécurité indépendant. N'\''inspecte que le périmètre concerné par la tâche. Identifie des faiblesses de sécurité concrètes avec leur contexte d'\''exploitation, les preuves, les fichiers touchés et la correction recommandée. Ne modifie aucun fichier. Distingue les problèmes confirmés des hypothèses.' ;;
    'Act as a focused technical researcher. Only study the question asked, favour reference evidence available in the environment, and give concise findings, uncertainties and the recommended action. Don'\''t modify any file.') _T='Agis comme chercheur technique ciblé. N'\''étudie que la question posée, privilégie les preuves de référence disponibles dans l'\''environnement, et rends des constats concis, les incertitudes et l'\''action recommandée. Ne modifie aucun fichier.' ;;
    'Error: unsupported role '\''%s'\''. Roles that write go through Codex (delegate-to-codex.sh) or a native subagent.') _T='Erreur : rôle non pris en charge '\''%s'\''. Les rôles qui écrivent passent par Codex (delegate-to-codex.sh) ou par un sous-agent natif.' ;;
    'Task handed over by the lead agent:') _T='Tâche confiée par l'\''orchestrateur :' ;;
    'You are a specialist. Don'\''t take over the project. Don'\''t modify any file in the repository. Give your result only to the lead agent. Reply in English.') _T='Tu es un spécialiste. Ne prends pas la direction du projet. Ne modifie aucun fichier du dépôt. Rends ton résultat uniquement à l'\''orchestrateur. Réponds en français.' ;;
    'delegate-to-claude: role=%s model=%s effort=%s max_turns=%s profile=%s') _T='delegate-to-claude : rôle=%s modèle=%s effort=%s tours_max=%s profil=%s' ;;
    'delegate-to-claude: this Claude Code version doesn'\''t know %s, trying again with '\''%s'\'' (run '\''claude update'\'').') _T='delegate-to-claude : cette version de Claude Code ne connaît pas %s, nouvel essai avec '\''%s'\'' (lancez '\''claude update'\'').' ;;
    'delegate-to-claude: %s unavailable for this account, falling back to %s (remembered for next time).') _T='delegate-to-claude : %s indisponible pour ce compte, repli sur %s (noté pour les prochaines fois).' ;;
    'delegate-to-claude: %ss · input tokens %s (%s cached), output %s · cost $%s') _T='delegate-to-claude : %ss · tokens entrée %s (dont %s en cache), sortie %s · coût $%s' ;;
    'You are the Executor. Do exactly the bounded task below, within the given scope. Follow the repository'\''s conventions, add or update tests for the changed behaviour, run the relevant checks, then stop. Don'\''t refactor anything outside the scope. If the task turns out to be ambiguous, cross-cutting or risky, stop without modifying any file and explain why it must be escalated.') _T='Tu es l'\''Exécutant. Réalise exactement la tâche bornée ci-dessous, dans le périmètre indiqué. Suis les conventions du dépôt, ajoute ou mets à jour les tests du comportement modifié, lance les vérifications pertinentes, puis arrête-toi. Ne refactore rien hors du périmètre. Si la tâche s'\''avère ambiguë, transverse ou risquée, arrête-toi sans modifier de fichier et explique pourquoi elle doit remonter d'\''un cran.' ;;
    'You are the Developer. Implement the feature or fix below within the given scope, following the repository'\''s conventions, with tests. Run the relevant checks and give the exact commands and their results. Stop and report if the change becomes cross-cutting or risky.') _T='Tu es le Développeur. Implémente la feature ou le correctif ci-dessous dans le périmètre indiqué, en suivant les conventions du dépôt, avec des tests. Lance les vérifications pertinentes et indique les commandes exactes et leurs résultats. Arrête-toi et rends compte si le changement devient transverse ou risqué.' ;;
    'You are the Documenter. Only update the documentation the task points to. Be accurate: check every statement against the code. Don'\''t modify source code.') _T='Tu es le Documentaliste. Ne mets à jour que la documentation indiquée par la tâche. Sois exact : vérifie chaque affirmation dans le code. Ne modifie pas le code source.' ;;
    'You are an independent Reviewer. Review the diff or files given in the task. Only report concrete defects: regressions, missed edge cases, security issues, missing tests, needless complexity, each with severity, file reference and evidence. Don'\''t modify any file. "No findings" is a valid answer.') _T='Tu es un Relecteur indépendant. Relis le diff ou les fichiers indiqués dans la tâche. Ne signale que des défauts concrets : régressions, cas limites oubliés, problèmes de sécurité, tests manquants, complexité inutile, chacun avec gravité, référence de fichier et preuve. Ne modifie aucun fichier. « Aucun constat » est une réponse valable.' ;;
    'You are the Explorer. Only answer the question asked, with short facts and path:line references. Don'\''t propose rewrites. Don'\''t modify any file.') _T='Tu es l'\''Explorateur. Réponds uniquement à la question posée, avec des faits courts et des références chemin:ligne. Ne propose pas de réécriture. Ne modifie aucun fichier.' ;;
    'You are the Debugger. Examine the evidence, rank the cause hypotheses, and propose the smallest, most discriminating checks or fixes. Don'\''t modify any file.') _T='Tu es le Débogueur. Examine les preuves, classe les hypothèses de cause, et propose les vérifications ou correctifs les plus petits et les plus discriminants. Ne modifie aucun fichier.' ;;
    'You are the Architect. Critique the design against the task and the repository'\''s constraints: trade-offs, coupling, simpler alternatives. Don'\''t modify any file.') _T='Tu es l'\''Architecte. Critique la conception au regard de la tâche et des contraintes du dépôt : arbitrages, couplage, alternatives plus simples. Ne modifie aucun fichier.' ;;
    'You are the Security reviewer. Only inspect the given scope. Report concrete weaknesses with their exploitability, evidence and fix, separating confirmed issues from hypotheses. Don'\''t modify any file.') _T='Tu es le Relecteur sécurité. N'\''inspecte que le périmètre donné. Signale des faiblesses concrètes avec leur exploitabilité, les preuves et la correction, en séparant les problèmes confirmés des hypothèses. Ne modifie aucun fichier.' ;;
    'Error: unsupported role '\''%s'\''.') _T='Erreur : rôle non pris en charge '\''%s'\''.' ;;
    'Error: Codex CLI not found (PATH, Codex.app or ChatGPT.app). Run loomy doctor.') _T='Erreur : CLI Codex introuvable (PATH, Codex.app ou ChatGPT.app). Lancez loomy doctor.' ;;
    'You are a specialist. Don'\''t take over the project. Give the lead agent a concise result: what you did or found, the files involved, the checks run and their results, the open risks. Reply in English.') _T='Tu es un spécialiste. Ne prends pas la direction du projet. Rends un résultat concis à l'\''orchestrateur : ce que tu as fait ou trouvé, les fichiers concernés, les vérifications lancées et leurs résultats, les risques ouverts. Réponds en français.' ;;
    'delegate-to-codex: role=%s model=%s effort=%s sandbox=%s profile=%s') _T='delegate-to-codex : rôle=%s modèle=%s effort=%s sandbox=%s profil=%s' ;;
    'delegate-to-codex: %s unavailable for this account, falling back to %s (remembered for next time).') _T='delegate-to-codex : %s indisponible pour ce compte, repli sur %s (noté pour les prochaines fois).' ;;
    'delegate-to-codex: codex exec failed (code %s). Last log lines:') _T='delegate-to-codex : échec de codex exec (code %s). Dernières lignes du journal :' ;;
    'delegate-to-codex: the working tree changed — review with '\''git diff'\'' before accepting:') _T='delegate-to-codex : le répertoire de travail a changé — relisez avec '\''git diff'\'' avant d'\''accepter :' ;;
    'delegate-to-codex: no file modified.') _T='delegate-to-codex : aucun fichier modifié.' ;;
    'delegate-to-codex: %ss · input tokens %s (%s cached), output %s · estimated cost $%s') _T='delegate-to-codex : %ss · tokens entrée %s (dont %s en cache), sortie %s · coût estimé $%s' ;;
    'To be decided') _T='À décider' ;;
    'The agent will propose a reasoned option during the interview.') _T='L'\''agent proposera une option argumentée pendant l'\''entretien.' ;;
    'Guides discovery (detected automatically, to confirm).') _T='Oriente la découverte (détecté automatiquement, à confirmer).' ;;
    'Defines how Codex and Claude Code share the work. Preselected from the detected tools.') _T='Définit comment Codex et Claude Code se partagent le travail. Pré-sélection selon les outils détectés.' ;;
    'One tool at a time: the simplest and cheapest.') _T='Un seul outil à la fois : le plus simple et le moins coûteux.' ;;
    'Both tools take turns, coordinated through Git and .ai/HANDOFF.md.') _T='Les deux outils travaillent tour à tour, coordonnés par Git et .ai/HANDOFF.md.' ;;
    'The lead agent delegates each role to the best model of both families (execution on GPT-6-Luna, architecture and security on Opus 5.5, cross review): best quality/cost ratio.') _T='L'\''orchestrateur délègue chaque rôle au meilleur modèle des deux familles (exécution sur GPT-6-Luna, architecture et sécurité sur Opus 5.5, revue croisée) : meilleur rapport qualité/coût.' ;;
    'Both at the same time on separate worktrees: faster, integration needs care.') _T='Les deux en même temps sur des worktrees séparés : plus rapide, intégration à soigner.' ;;
    'The main tool hosts the lead agent: it plans, delegates, decides and checks. It deserves the best reasoning.') _T='L'\''outil principal porte l'\''orchestrateur : il planifie, délègue, décide et vérifie. C'\''est lui qui mérite le meilleur raisonnement.' ;;
